// #0d245d (6a993d6f2695665e8e0d245d) — домен 1 «פתיחת השיחה והצגת המטרה»: статус текстом с точкой (не «пилюля»), цитата в «…»
// с линией с inline-start стороны, время «00:05 ▶», без строки «אחד מארבעת…» (реджект 13.10 по Figma 678:654/685:773);
// звонок короче 30 с → «השיחה נקטעה בשניות הראשונות… אין מספיק מידע» (правило 21.10, #57977a).
// По ГОТОВЫМ отчётам: QA-bf7c47-2110 (цитата 00:05) и QA-57977a-27s-2110 (26 с). Кейсы REP-008, REP-009. Только чтение → @prod-safe.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { openReport } from './support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#0d245d · #6a993d6f2695665e8e0d245d';
const CANDIDATE = process.env.QA_OPENING_CANDIDATE || 'QA-bf7c47-2110';
const CUT_OFF_CANDIDATE = process.env.QA_CUT_OFF_CANDIDATE || 'QA-57977a-27s-2110';

test.describe(`Отчёт — домен «פתיחת השיחה והצגת המטרה» (${HASH})`, () => {
  test(`${CANDIDATE}: статус с точкой без «пилюли», цитата «…» с линией inline-start, время «00:05 ▶», нет «אחד מארבעת…» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openReport(page, CANDIDATE);
    const domain = page.locator('[data-testid="report-domain"][data-domain="opening"]');
    await expect(domain).toHaveCount(1);
    await expect(domain.getByRole('heading', { level: 3 })).toContainText('פתיחת השיחה והצגת המטרה');

    // Источник: Figma 678:654 / 685:773 — состояние текстом с точкой, без рамки и заливки «пилюли».
    const state = domain.locator(':scope > header [data-testid="domain-state"]');
    await expect(state).toHaveCount(1);
    await expect(state.locator('img'), 'точка состояния').toHaveCount(1);
    const look = await state.evaluate((el) => {
      const s = getComputedStyle(el);
      return { bg: s.backgroundColor, border: parseFloat(s.borderTopWidth) || 0 };
    });
    expect(look.bg, 'у состояния нет заливки').toMatch(/^(transparent|rgba\(\d+, \d+, \d+, 0\))$/);
    expect(look.border, 'у состояния нет рамки').toBe(0);

    // Цитата домена: «…» и линия с inline-start стороны (в RTL — справа).
    const quote = domain.getByTestId('domain-evidence').getByTestId('evidence-quote').first();
    await expect(quote).toBeVisible();
    const q = await quote.evaluate((el) => {
      const s = getComputedStyle(el);
      return { text: (el as HTMLElement).innerText.trim(), width: parseFloat(s.borderInlineStartWidth) || 0, style: s.borderInlineStartStyle };
    });
    expect(q.text.startsWith('«') && q.text.endsWith('»'), `цитата в «…»: ${q.text}`).toBeTruthy();
    expect(q.width, 'линия цитаты inline-start').toBeGreaterThan(0);
    expect(q.style).not.toBe('none');

    // Время цитаты: «00:05» (mm:ss) и значок воспроизведения.
    const time = domain.getByTestId('domain-evidence').getByTestId('evidence-time').first();
    await expect(time).toHaveText('00:05');
    await expect(time.locator('img')).toHaveCount(1);

    // Лишней строки «אחד מארבעת…» нет.
    await expect(page.locator('main')).not.toContainText('אחד מארבעת');
  });

  test(`${CUT_OFF_CANDIDATE} (26 с): домен — «השיחה נקטעה בשניות הראשונות… אין מספיק מידע» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openReport(page, CUT_OFF_CANDIDATE);
    const domain = page.locator('[data-testid="report-domain"][data-domain="opening"]');
    // Источник: AC (короткий звонок) + правило «короче 30 с = נקטעה בשניות הראשונות» (пользователь 21.10).
    const state = domain.locator(':scope > header [data-testid="domain-state"]');
    await expect(state).toHaveAttribute('data-state', 'insufficient_information');
    await expect(state).toHaveText('אין מספיק מידע להערכה');
    const explanation = domain.getByTestId('domain-explanation');
    await expect(explanation).toContainText('השיחה נקטעה בשניות הראשונות');
    await expect(explanation).toContainText('אין בה מספיק מידע');
  });
});
